38	/**
39	 * Helper class to manage a group of mutable rate metrics.
40	 *
41	 * Each thread will maintain a local rate count, and upon snapshot,
42	 * these values will be aggregated into a global rate. This class
43	 * should only be used for long running threads, as any metrics
44	 * produced between the last snapshot and the death of a thread
45	 * will be lost. This allows for significantly higher concurrency
46	 * than {@link MutableRates}. See HADOOP-24420.
47	 */
48	@InterfaceAudience.Public
49	@InterfaceStability.Evolving
50	public class MutableRatesWithAggregation extends MutableMetric {
51	  static final Logger LOG =
52	      LoggerFactory.getLogger(MutableRatesWithAggregation.class);
53	  private final Map<String, MutableRate> globalMetrics =
54	      new ConcurrentHashMap<>();
55	  private final Set<Class<?>> protocolCache = Sets.newHashSet();
56	
57	  private final ConcurrentLinkedDeque<WeakReference<ConcurrentMap<String, ThreadSafeSampleStat>>>
58	      weakReferenceQueue = new ConcurrentLinkedDeque<>();
59	  private final ThreadLocal<ConcurrentMap<String, ThreadSafeSampleStat>>
60	      threadLocalMetricsMap = new ThreadLocal<>();
61	  // prefix for metric name
62	  private String typePrefix = "";
63	
64	  /**
65	   * Initialize the registry with all the methods in a protocol
66	   * so they all show up in the first snapshot.
67	   * Convenient for JMX implementations.
68	   * @param protocol the protocol class
69	   */
70	  public void init(Class<?> protocol) {
71	    if (protocolCache.contains(protocol)) {
72	      return;
73	    }
74	    protocolCache.add(protocol);
75	    for (Method method : protocol.getDeclaredMethods()) {
76	      String name = method.getName();
77	      LOG.debug(name);
78	      addMetricIfNotExists(name);
79	    }
80	  }
81	
82	  /**
83	   * Initialize the registry with all rate names passed in.
84	   * This is an alternative to the above init function since this metric
85	   * can be used more than just for rpc name.
86	   * @param names the array of all rate names
87	   */
88	  public void init(String[] names) {
89	    for (String name : names) {
90	      addMetricIfNotExists(name);
91	    }
92	  }
