94	  /**
95	   * Add a rate sample for a rate metric.
96	   * @param name of the rate metric
97	   * @param elapsed time
98	   */
99	  public void add(String name, long elapsed) {
100	    ConcurrentMap<String, ThreadSafeSampleStat> localStats =
101	        threadLocalMetricsMap.get();
102	    if (localStats == null) {
103	      localStats = new ConcurrentHashMap<>();
104	      threadLocalMetricsMap.set(localStats);
105	      weakReferenceQueue.add(new WeakReference<>(localStats));
106	    }
107	    ThreadSafeSampleStat stat = localStats.get(name);
108	    if (stat == null) {
109	      stat = new ThreadSafeSampleStat();
110	      localStats.put(name, stat);
111	    }
112	    stat.add(elapsed);
113	  }
114	
115	  @Override
116	  public synchronized void snapshot(MetricsRecordBuilder rb, boolean all) {
117	    Iterator<WeakReference<ConcurrentMap<String, ThreadSafeSampleStat>>> iter =
118	        weakReferenceQueue.iterator();
119	    while (iter.hasNext()) {
120	      ConcurrentMap<String, ThreadSafeSampleStat> map = iter.next().get();
121	      if (map == null) {
122	        // Thread has died; clean up its state
123	        iter.remove();
124	      } else {
125	        aggregateLocalStatesToGlobalMetrics(map);
126	      }
127	    }
128	    for (MutableRate globalMetric : globalMetrics.values()) {
129	      globalMetric.snapshot(rb, all);
130	    }
131	  }
132	
133	  /**
134	   * Collects states maintained in {@link ThreadLocal}, if any.
135	   */
136	  synchronized void collectThreadLocalStates() {
137	    final ConcurrentMap<String, ThreadSafeSampleStat> localStats =
138	        threadLocalMetricsMap.get();
139	    if (localStats != null) {
140	      aggregateLocalStatesToGlobalMetrics(localStats);
141	    }
142	  }
143	
144	  /**
145	   * Aggregates the thread's local samples into the global metrics. The caller
146	   * should ensure its thread safety.
147	   */
148	  private void aggregateLocalStatesToGlobalMetrics(
149	      final ConcurrentMap<String, ThreadSafeSampleStat> localStats) {
150	    for (Map.Entry<String, ThreadSafeSampleStat> entry : localStats
151	        .entrySet()) {
152	      String name = entry.getKey();
153	      MutableRate globalMetric = addMetricIfNotExists(name);
154	      entry.getValue().snapshotInto(globalMetric);
155	    }
156	  }
157	
158	  Map<String, MutableRate> getGlobalMetrics() {
159	    return globalMetrics;
160	  }
161	
162	  private synchronized MutableRate addMetricIfNotExists(String name) {
163	    MutableRate metric = globalMetrics.get(name);
164	    if (metric == null) {
165	      metric = new MutableRate(name + typePrefix, name + typePrefix, false);
166	      metric.setUpdateTimeStamp(true);
167	      globalMetrics.put(name, metric);
168	    }
169	    return metric;
170	  }
171	
172	  private static class ThreadSafeSampleStat {
173	
174	    private SampleStat stat = new SampleStat();
175	
176	    synchronized void add(double x) {
177	      stat.add(x);
178	    }
179	
180	    synchronized void snapshotInto(MutableRate metric) {
181	      if (stat.numSamples() > 0) {
182	        metric.add(stat.numSamples(), Math.round(stat.total()));
183	        stat.reset();
184	      }
185	    }
186	  }
187	
188	  public void init(Class<?> protocol, String prefix) {
189	    this.typePrefix = prefix;
190	    init(protocol);
191	  }
