582	      private RpcWritable call(RPC.Server server,
583	          String connectionProtocolName, RpcWritable.Buffer request,
584	          String methodName, ProtoClassProtoImpl protocolImpl)
585	          throws Exception {
586	        BlockingService service = (BlockingService) protocolImpl.protocolImpl;
587	        MethodDescriptor methodDescriptor = service.getDescriptorForType()
588	            .findMethodByName(methodName);
589	        if (methodDescriptor == null) {
590	          String msg = "Unknown method " + methodName + " called on "
591	                                + connectionProtocolName + " protocol.";
592	          LOG.warn(msg);
593	          throw new RpcNoSuchMethodException(msg);
594	        }
595	        Message prototype = service.getRequestPrototype(methodDescriptor);
596	        Message param = request.getValue(prototype);
597	
598	        Message result;
599	        Call currentCall = Server.getCurCall().get();
600	        try {
601	          server.rpcDetailedMetrics.init(protocolImpl.protocolClass);
602	          CURRENT_CALL_INFO.set(new CallInfo(server, methodName));
603	          currentCall.setDetailedMetricsName(methodName);
604	          result = service.callBlockingMethod(methodDescriptor, null, param);
605	          // Check if this needs to be a deferred response,
606	          // by checking the ThreadLocal callback being set
607	          if (CURRENT_CALLBACK.get() != null) {
608	            currentCall.deferResponse();
609	            CURRENT_CALLBACK.set(null);
610	            return null;
611	          }
612	        } catch (ServiceException e) {
613	          Exception exception = (Exception) e.getCause();
614	          currentCall.setDetailedMetricsName(
615	              exception.getClass().getSimpleName());
616	          throw (Exception) e.getCause();
617	        } catch (Exception e) {
618	          currentCall.setDetailedMetricsName(e.getClass().getSimpleName());
619	          throw e;
620	        } finally {
621	          CURRENT_CALL_INFO.set(null);
622	        }
623	        return RpcWritable.wrap(result);
624	      }
625	    }
